            best[0] = 0
            min_heap = [(best[0], 0)]
            while min_heap:
                curr, u = heapq.heappop(min_heap)
                if curr != best[u]:
                    continue
                if u == len(adj)-1:
                    return curr
                for v, s, e in adj[u]:
                    if curr > e:
                        continue
                    if not (best[v] > max(curr, s)+1):
                        continue
                    best[v] = max(curr, s)+1
                    heapq.heappush(min_heap, (best[v], v))
            return -1

        adj = [[] for _ in range(n)]
        for u, v, s, e in edges:
            adj[u].append((v, s, e))
        return dijkstra()

